    {
      "claim": "En cas d’urgence à l’étranger, il faut composer immédiatement le numéro d’urgence local du pays.",
      "verdict": "supported"
    },
    {
      "claim": "Les numéros d’urgence locaux incluent le 112 en Europe et le 911 aux États-Unis.",
      "verdict": "supported"
    }
